{
  "probability": 0.88,
  "range_low": 0.80,
  "range_high": 0.96,
  "summary": [
    "Early-2026 pace on the Central Mediterranean route reached 606–699 deaths by February, suggesting a high pace that could push the total beyond 1,000 by May if sustained.",
    "Historical annual tolls on the Central Mediterranean route (~2,100–2,450 per year) imply that a large portion of yearly deaths can occur in the first half of the year, making 1,000+ by May plausible.",
    "Spring seasonality, policy dynamics, and SAR capacity constraints collectively bias upward the likelihood of reaching 1,000+ by May, though reporting lags and potential SAR improvements introduce uncertainty.",
    "Overall, the calibrated posterior probability is high (0.88) with a plausible range extending from ~0.80 to ~0.96."
  ],
  "confidence": "high",
  "narrative": "Using the IOM Central Mediterranean reference class and current early-2026 signals, the calibrated probability that 1,000+ Mediterranean deaths are recorded before May 2026 is 0.88. While signaling is strong due to pace and historical tolls, uncertainties from reporting delays and weather/SAR dynamics keep the estimate within a broad range around this level.",
  "justification": {
    "anchor": {
      "probability": 0.85,
      "basis": "Reference class is annual Central Mediterranean fatalities per IOM Missing Migrants Project; the forecasted 606–699 deaths by February 2026 imply a non-negligible probability of crossing 1,000 before May, which aligns with a mid-to-high anchor around 0.85."
    },
    "factor_updates": [
      {
        "factor": "Early-2026 pace on Central Mediterranean route",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "By February 2026, 606–699 deaths were recorded; sustaining this pace through March–May could push the total beyond 1,000."
      },
      {
        "factor": "Historical annual central Mediterranean toll level",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Historical totals around 2,100–2,450 per year mean a substantial share of deaths can occur early in the year, supporting 1,000+ by May."
      },
      {
        "factor": "Policy/deterrence reducing safe pathways",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Tighter policies may push migrants toward riskier crossings, increasing fatalities and contributing to a higher likelihood of reaching 1,000 by May."
      },
      {
        "factor": "Spring seasonality increasing crossing frequency",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Improved sea conditions and longer daylight in spring typically raise crossing activity and associated fatalities."
      },
      {
        "factor": "Data reporting lags and revisions in IOM tallies",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Counts may be underreported in early tallies and revised upward later; this adds uncertainty but does not decisively push the result in a single direction."
      }
    ],
    "synthesis_rationale": "The strongest updates come from the high early-2026 death pace and the substantial historical toll, which together imply meaningful probability of exceeding 1,000 by May. Moderating factors include reporting lags and potential SAR improvements or adverse weather, which justify a calibrated probability in the high 0.80s with a wide but plausible range."
  }
}

